import "./App.css";
import { Routes, Route, Navigate } from "react-router-dom";
import Dashboard from "./components/dashboard";

function App() {
  return (
    <Routes>
      <Route path="/" element={<Navigate to="/home" replace={true} />} />
      {/* No login flow yet — Dashboard falls back to a generic "Clinician"
          user when localStorage has none, so it works standalone. */}
      <Route path="/home" element={<Dashboard onLogout={() => {}} />} />
    </Routes>
  );
}

export default App;
